import {VERSION,uid,today,currentYear,amount,validDate,emptyData,eventTotals,debtRemaining,newEvent,addPayment,addOutflow,closeCollection,closeEvent,addRepayment,annualCandidates,birthdayCandidates,demoData,validateData} from './model.js';
const KEY='svoi-dengi-v1';
let data=emptyData(),lastRaw=null,loadError='',section='events',selectedId='',year=currentYear(),filter='active',mobileDetail=false,debtFilter='active',installPrompt=null,offlineReady=false;
const app=document.getElementById('app'),modal=document.getElementById('modal');
try{lastRaw=localStorage.getItem(KEY);if(lastRaw)data=validateData(JSON.parse(lastRaw));}catch(error){loadError='Не удалось прочитать данные устройства. Они не перезаписаны. Восстановите резервную копию в настройках.';}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:n%100?2:0}).format(n/100);
const rawRub=n=>String(n/100);
const dateText=s=>s?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(s+'T12:00:00')):'Без срока';
const shortDate=s=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short'}).format(new Date(s+'T12:00:00'));
const initials=s=>s.split(' ').slice(0,2).map(x=>x[0]).join('');
const icons={gift:'<path d="M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8C8 8 6 6 6 4s3-2 6 4Zm0 0c4 0 6-2 6-4s-3-2-6 4Z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-4M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>',wallet:'<path d="M20 8V5H5a3 3 0 0 0 0 6h16v9H5a3 3 0 0 1-3-3V8M21 11v5h-6v-5Z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1v3l-2 2 2 2v3l3 1 1 3h6l1-3 3-1v-3l2-2-2-2V7l-3-1-1-3Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',back:'<path d="m15 18-6-6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',trash:'<path d="M3 6h18M5 6l1 15h12l1-15M9 6V3h6v3M10 10v7M14 10v7"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.gift}</svg>`;
const navItems=[['events','gift','Сборы'],['debts','wallet','Долги'],['people','users','Коллеги'],['settings','settings','Настройки']];
const nav=bottom=>`<nav class="${bottom?'bottomnav':'topnav'}" aria-label="Разделы">${navItems.map(([id,i,label])=>`<button data-action="nav" data-id="${id}" class="${section===id?'selected':''}" ${section===id?'aria-current="page"':''}>${bottom?icon(i):''}${label}</button>`).join('')}</nav>`;
function notify(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function commit(fn,message,force=false){
  if(loadError&&!force)throw new Error('Данные не были загружены. Сначала восстановите резервную копию.');
  if(!force&&localStorage.getItem(KEY)!==lastRaw)throw new Error('Данные изменились в другой вкладке. Закройте форму и повторите действие.');
  const copy=structuredClone(data);fn(copy);const validated=validateData(copy),json=JSON.stringify(validated);
  try{localStorage.setItem(KEY,json);}catch{throw new Error('Не удалось сохранить данные. Проверьте доступ к хранилищу или освободите место.');}
  data=validated;lastRaw=json;loadError='';render();if(message)notify(message);
}
const activeEvent=()=>data.events.find(e=>e.id===selectedId);
const personName=(e,id)=>e.participants.find(p=>p.personId===id)?.name||'Участник';
const status=e=>e.closed?'<span class="badge complete">Расчёты завершены</span>':e.collectionClosed?'<span class="badge complete">Сбор завершён</span><span class="badge neutral">Расчёты идут</span>':'<span class="badge">Сбор открыт</span>';
function render(){
 app.innerHTML=`<header class="topbar"><div><div class="brand">Свои деньги<em>.</em></div><div class="muted small">Личные финансы · мероприятия и долги</div></div>${nav(false)}<div class="local"><span class="dot"></span>${!navigator.onLine?'Без интернета':offlineReady?'Сохранено на устройстве':'Данные на этом устройстве'}</div><button class="topicon" data-action="backup" aria-label="Скачать резервную копию">${icon('download')}</button></header><main>${loadError?`<div class="banner" role="alert">${esc(loadError)}</div>`:''}${section==='events'?eventsView():section==='debts'?debtsView():section==='people'?peopleView():settingsView()}</main>${nav(true)}`;
}
function years(){return [...new Set([currentYear(),year,...data.events.map(e=>Number(e.date.slice(0,4)))])].sort((a,b)=>a-b);}
function eventsView(){
 const all=data.events.filter(e=>Number(e.date.slice(0,4))===year),shown=all.filter(e=>filter==='archive'?e.closed:!e.closed).sort((a,b)=>a.date.localeCompare(b.date));
 if(!shown.some(e=>e.id===selectedId)){selectedId=shown[0]?.id||'';mobileDetail=false;}
 const totals=all.filter(e=>!e.closed).map(eventTotals),remaining=totals.reduce((a,t)=>a+Math.max(0,t.remaining),0),advance=totals.reduce((a,t)=>a+Math.max(0,-t.remaining),0);
 const event=activeEvent();
 return `<div class="heading"><div><h1>Мероприятия</h1><div class="muted">Сборы коллег, подарки и общие события</div></div><button class="primary row" data-action="new-event">${icon('plus')}<span>Новый сбор</span></button></div><div class="hero"><div><div>Мне осталось передать</div><div class="value mono">${rub(remaining)}</div><div class="caption">По всем открытым мероприятиям · ${year}</div></div>${advance?`<div class="sub"><div class="caption">Передано авансом</div><div class="value mono">${rub(advance)}</div></div>`:`<div class="sub"><div class="caption">Открытых сборов</div><div class="value">${all.filter(e=>!e.closed).length}</div></div>`}</div><div class="columns ${mobileDetail?'mobile-detail':'mobile-list'}"><aside class="event-list"><div class="row between listheader"><h3>Сборы</h3><label><span class="visually-hidden">Год сборов</span><select id="year" class="year">${years().map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="segmented"><button class="${filter==='active'?'selected':''}" data-action="filter" data-id="active">Текущие · ${all.filter(e=>!e.closed).length}</button><button class="${filter==='archive'?'selected':''}" data-action="filter" data-id="archive">Архив · ${all.filter(e=>e.closed).length}</button></div>${shown.length?shown.map(e=>{const t=eventTotals(e),d=new Date(e.date+'T12:00:00');return `<button class="event-card ${e.id===selectedId?'selected':''}" data-action="select-event" data-id="${esc(e.id)}"><span class="date-tile">${d.getDate()}<span>${d.toLocaleDateString('ru-RU',{month:'short'}).replace('.','')}</span></span><span class="grow"><strong>${esc(e.title)}</strong><span class="muted">${rub(t.collected)} собрано</span><span class="badges">${status(e)}</span></span><span class="chevron">${icon('arrow')}</span></button>`}).join(''):`<div class="empty"><div class="symbol">${icon('gift')}</div><h3>${filter==='archive'?'Пока без архива':'Начнём со сбора'}</h3><p class="muted">${filter==='archive'?'Здесь будут мероприятия с завершёнными расчётами.':'Добавьте коллег и создайте первое мероприятие.'}</p>${filter==='active'?'<button class="primary" data-action="new-event">Создать сбор</button>':''}</div>`}<div class="year-tools"><button data-action="birthdays">Создать дни рождения</button><button data-action="next-year">На следующий год</button></div>${!data.people.length?'<button class="textlink full" data-action="new-person">＋ Добавить первого коллегу</button>':''}${!data.events.length&&!data.people.length?'<button class="textlink full" data-action="demo">Посмотреть пример</button>':''}</aside><section class="event-detail">${event?eventView(event):'<div class="empty"><h3>Всё начинается с людей</h3><p class="muted">Сначала добавьте коллег и их дни рождения. Затем создавайте разовые сборы или сразу весь год.</p><button class="secondary" data-action="new-person">Добавить коллегу</button></div>'}</section></div>`;
}
function eventView(e){
 const t=eventTotals(e),included=e.participants.filter(p=>p.included),paid=included.filter(p=>t.received(p.personId)>=p.expected).length;
 const ledger=[...e.payments.map(p=>({...p,incoming:true,name:personName(e,p.personId)})),...e.outflows.map(p=>({...p,incoming:false,name:{transfer:'Передано',expense:'Расход',return:'Возврат участнику'}[p.kind]}))].sort((a,b)=>b.date.localeCompare(a.date));
 return `<button class="back-mobile row" data-action="back">${icon('back')}Все сборы</button><div class="panel"><div class="row between detailtop"><div class="grow"><div class="muted">${dateText(e.date)}${e.monthly?' · взносы по месяцам':''}</div><h2>${esc(e.title)}</h2><div class="badges">${status(e)}</div></div><button class="topicon" data-action="edit-event" aria-label="Настройки мероприятия">${icon('settings')}</button></div><div class="stats"><div><span class="muted">Собрано</span><strong class="mono">${rub(t.collected)}</strong></div><div><span class="muted">Передано / расходы</span><strong class="mono">${rub(t.transferred)}</strong></div><div><span class="muted">${t.remaining<0?'Передано авансом':'Осталось передать'}</span><strong class="mono">${rub(Math.abs(t.remaining))}</strong></div></div><div class="row between"><h3>Участники</h3><span class="muted">${paid} из ${included.length} сдали</span></div><div class="progress" role="progressbar" aria-label="Собрано от запланированной суммы" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(t.expected?t.collected/t.expected*100:0))}"><span style="width:${Math.min(100,t.expected?t.collected/t.expected*100:0)}%"></span></div><div class="muted small">План ${rub(t.expected)}${t.collected>t.expected?' · собрано больше плана':''}</div>${e.participants.map(p=>{const received=t.received(p.personId);return `<div class="person-row ${!p.included?'exempt':''}"><span class="initial">${esc(initials(p.name))}</span><div class="grow name">${esc(p.name)}<div class="muted small">${!p.included?esc(p.reason||'Не участвует')+(received?' · ранее сдал '+rub(received):''):received>=p.expected?'Взнос получен':received?'Осталось сдать '+rub(p.expected-received):'Ещё не сдал · '+rub(p.expected)}</div></div>${p.included?`<button class="pay ${received>=p.expected?'paid':received?'partial':''}" data-action="payment" data-id="${esc(p.personId)}" ${e.collectionClosed||e.closed?'disabled':''}>${received?(received>=p.expected?'✓ ':'')+rub(received):'＋ Взнос'}</button>`:'<span>—</span>'}</div>`}).join('')}${!e.participants.length?'<p class="footnote">Участников пока нет. Добавьте коллег, затем откройте настройки сбора.</p>':''}<div class="actions">${!e.closed?`<button class="primary" data-action="outflow">Передать / потратить</button>${!e.collectionClosed?`<button class="secondary" data-action="finish-collection" ${!t.complete?'disabled':''}>Завершить сбор</button>`:`<button class="secondary" data-action="finish-event" ${t.remaining!==0?'disabled':''}>Завершить расчёты</button>`}`:`<button class="secondary" data-action="reopen-event">Возобновить расчёты</button>`}</div><p class="footnote">${e.closed?'Все расчёты завершены. Мероприятие в архиве.':e.collectionClosed?'Деньги собраны. Проведите передачи, расходы и возвраты до нулевого остатка.':'Сумма — полученные деньги. Пустой взнос — оплаты нет. Серый — не участвует.'}</p>${e.collectionClosed&&!e.closed?'<button class="textlink" data-action="reopen-collection">Возобновить сбор</button>':''}${e.monthly?monthlyView(e):''}<details><summary class="section-title">История операций · ${ledger.length}</summary>${ledger.length?ledger.map(p=>`<div class="transaction ${p.incoming?'incoming':''}"><div class="grow"><div>${esc(p.name)}</div><div class="muted small">${shortDate(p.date)}${p.note?' · '+esc(p.note):''}</div></div><strong class="mono">${p.incoming?'+':'−'}${rub(p.amount)}</strong><button class="delete" data-action="delete-operation" data-id="${esc(p.id)}" data-kind="${p.incoming?'payment':'outflow'}" aria-label="Удалить операцию" ${e.closed||p.incoming&&e.collectionClosed?'disabled':''}>${icon('trash')}</button></div>`).join(''):'<p class="footnote">Операций пока нет.</p>'}</details></div>`;
}
function monthlyView(e){
 const months=[...new Set(e.payments.map(p=>p.date.slice(0,7)))].sort();
 if(!months.length)return '';
 return `<details><summary class="section-title">Взносы по месяцам</summary><div class="month-table"><table><thead><tr><th>Участник</th>${months.map(m=>`<th>${new Date(m+'-01T12:00:00').toLocaleDateString('ru-RU',{month:'short',year:'2-digit'})}</th>`).join('')}<th>Всего</th></tr></thead><tbody>${e.participants.map(p=>`<tr><td>${esc(p.name)}</td>${months.map(m=>{const n=e.payments.filter(x=>x.personId===p.personId&&x.date.startsWith(m)).reduce((a,x)=>a+x.amount,0);return `<td>${n?rub(n):'—'}</td>`}).join('')}<td>${rub(eventTotals(e).received(p.personId))}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function debtsView(){
 const total=data.debts.reduce((a,d)=>a+debtRemaining(d),0),shown=data.debts.filter(d=>debtFilter==='active'?debtRemaining(d)>0:debtRemaining(d)===0);
 return `<div class="heading"><div><h1>Личные долги</h1><div class="muted">Деньги, которые ты дал конкретному человеку</div></div><button class="primary row" data-action="new-debt">${icon('plus')}Я дал в долг</button></div><div class="hero"><div><div>Мне должны вернуть</div><div class="value mono">${rub(total)}</div><div class="caption">Отдельно от сборов на мероприятия</div></div></div><div class="segmented" style="max-width:420px"><button class="${debtFilter==='active'?'selected':''}" data-action="debt-filter" data-id="active">Не возвращены</button><button class="${debtFilter==='closed'?'selected':''}" data-action="debt-filter" data-id="closed">Возвращены</button></div>${shown.length?`<div class="debt-grid">${shown.map(d=>`<article class="panel debt-card"><div class="row between"><h3>${esc(d.name)}</h3><span class="badge ${debtRemaining(d)===0?'complete':d.due&&d.due<today()?'':'neutral'}">${debtRemaining(d)===0?'Возвращён':d.due&&d.due<today()?'Срок прошёл':'В долг'}</span></div><div class="value mono">${rub(debtRemaining(d))}</div><div class="muted">Осталось вернуть · выдано ${rub(d.amount)}</div><div class="detail ${d.due&&d.due<today()&&debtRemaining(d)>0?'overdue':''}">Выдано ${dateText(d.date)}<br>Срок: ${dateText(d.due)}</div>${d.note?`<p class="muted">${esc(d.note)}</p>`:''}${debtRemaining(d)>0?`<button class="primary full" data-action="repayment" data-id="${esc(d.id)}">Отметить возврат</button>`:''}<details><summary class="section-title">Возвраты · ${d.repayments.length}</summary>${d.repayments.map(p=>`<div class="transaction"><div class="grow">${dateText(p.date)}<div class="muted small">${esc(p.note)}</div></div><strong>${rub(p.amount)}</strong><button class="delete" data-action="delete-repayment" data-id="${esc(p.id)}" data-debt="${esc(d.id)}" aria-label="Удалить возврат">${icon('trash')}</button></div>`).join('')}</details><button class="textlink" data-action="edit-debt" data-id="${esc(d.id)}">Изменить запись</button></article>`).join('')}</div>`:`<div class="empty"><div class="symbol">${icon('wallet')}</div><h3>${debtFilter==='active'?'Тебе пока никто не должен':'Возвращённых долгов пока нет'}</h3><p class="muted">Записывай выдачу денег и каждый частичный возврат. Остаток пересчитывается автоматически.</p><button class="primary" data-action="new-debt">Я дал в долг</button></div>`}`;
}
function peopleView(){return `<div class="heading"><div><h1>Коллеги</h1><div class="muted">Участники сборов и календарь дней рождения</div></div><button class="primary row" data-action="new-person">${icon('plus')}Добавить</button></div>${data.people.length?`<div class="people-grid">${data.people.map(p=>`<article class="panel people-card"><span class="initial">${esc(initials(p.name))}</span><div class="grow"><h3>${esc(p.name)}</h3><div class="muted">${p.birthday?'ДР: '+shortDate('2000-'+p.birthday):'День рождения не указан'}${p.phone?' · '+esc(p.phone):''}</div>${!p.active?'<span class="badge neutral">Больше не работает</span>':''}</div><button class="topicon" data-action="edit-person" data-id="${esc(p.id)}" aria-label="Изменить коллегу">${icon('settings')}</button></article>`).join('')}</div>`:`<div class="empty"><h3>Добавь участников</h3><p class="muted">Именинника автоматически исключим из сбора на его день рождения. Ушедшие коллеги сохранятся в истории.</p><button class="primary" data-action="new-person">Добавить коллегу</button></div>`}`;}
function settingsView(){return `<div class="heading"><div><h1>Настройки</h1><div class="muted">Данные и приложение</div></div></div><div class="settings"><section class="panel"><h3>Данные на устройстве</h3><p>Записи хранятся в этом браузере. Между телефоном и планшетом автоматической синхронизации пока нет. Очистка данных браузера удалит записи: сохраняйте резервную копию.</p><div class="actions"><button class="primary" data-action="backup">Скачать копию</button><button class="secondary" data-action="import">Восстановить из файла</button></div></section><section class="panel"><h3>Установка на телефон</h3><p>${window.matchMedia('(display-mode: standalone)').matches?'Приложение уже открыто в отдельном окне.':installPrompt?'Установите приложение: оно появится на главном экране.':'Android: меню браузера → «Установить приложение» или «Добавить на главный экран». iPhone / iPad: Safari → «Поделиться» → «На экран Домой». Для установки используйте опубликованную HTTPS-ссылку.'}</p>${installPrompt?'<button class="primary" data-action="install">Установить приложение</button>':''}<div class="muted">${offlineReady?'✓ Приложение готово к работе без интернета':'Подготовка офлайн-режима…'}</div></section><section class="panel"><h3>Взнос по умолчанию</h3><p>Применяется к новым сборам. В каждом мероприятии сумму можно изменить отдельно для каждого участника.</p><button class="secondary" data-action="default-amount">${rub(data.defaultAmount)} · изменить</button></section><section class="panel"><h3>Планирование года</h3><p>Создайте все дни рождения или повторите выбранные регулярные сборы на следующий год. Оплаты и проведённые расчёты не переносятся.</p><div class="actions"><button class="secondary" data-action="birthdays">Дни рождения</button><button class="secondary" data-action="next-year">Следующий год</button></div></section>${!data.events.length&&!data.people.length?'<section class="panel"><h3>Попробовать на примере</h3><p>Загрузить демонстрационные сборы, коллег и один личный долг.</p><button class="secondary" data-action="demo">Включить пример</button></section>':''}<section class="panel"><h3>О первой версии</h3><p>Свои деньги · версия 1.0. Мероприятия, личные долги и учёт коллег. Брокерский счёт не включён.</p><button class="danger secondary" data-action="reset">Очистить все данные</button></section></div>`;}
function openForm(title,body,submit,onSubmit){
 modal.innerHTML=`<form><header class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button type="button" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></header><div class="modal-body">${body}<div class="error" role="alert"></div><div class="modal-buttons"><button type="button" class="secondary" data-action="close-modal">Отмена</button><button class="primary" type="submit">${esc(submit)}</button></div></div></form>`;
 modal.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const error=modal.querySelector('.error');try{await onSubmit(new FormData(ev.target),ev.target);modal.close();}catch(e){error.textContent=e.message;}};
 modal.showModal();
}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
const noteField=value=>`<label class="field">Комментарий <span class="muted">· необязательно</span><textarea name="note" maxlength="500">${esc(value||'')}</textarea></label>`;
function confirmAction(title,message,fn,label='Подтвердить'){openForm(title,`<p>${esc(message)}</p>`,label,()=>fn());}
function personForm(id){
 const p=data.people.find(p=>p.id===id);
 openForm(p?'Изменить коллегу':'Новый коллега',field('Имя и фамилия','name',p?.name||'','text','required maxlength="200" autocomplete="name"')+`<div class="fields">${field('День рождения · день','day',p?.birthday?Number(p.birthday.slice(3)):'','number','min="1" max="31" inputmode="numeric"')}${field('Месяц','month',p?.birthday?Number(p.birthday.slice(0,2)):'','number','min="1" max="12" inputmode="numeric"')}</div>`+field('Телефон · необязательно','phone',p?.phone||'','tel','maxlength="100"')+`<label class="check"><input type="checkbox" name="active" ${!p||p.active?'checked':''}>Работает и участвует в новых сборах</label>${p?'<p class="footnote">Изменение статуса влияет на новые сборы. В уже созданных мероприятиях состав меняется отдельно.</p>':''}`,'Сохранить',f=>{
  const name=f.get('name').trim(),day=f.get('day'),month=f.get('month');if(!name)throw new Error('Введите имя.');
  const birthday=day&&month?`${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`:'';
  if((day&&!month)||(!day&&month)||(birthday&&!validDate('2000-'+birthday)))throw new Error('Проверьте день и месяц рождения.');
  commit(copy=>{const value={id:p?.id||uid(),name,birthday,phone:f.get('phone').trim(),active:f.has('active')};const i=copy.people.findIndex(x=>x.id===p?.id);if(i>=0)copy.people[i]=value;else copy.people.push(value);},'Коллега сохранён');
 });
}
function eventForm(edit=false){
 const e=edit?activeEvent():null;
 if(!data.people.some(p=>p.active)&&!e){personForm();notify('Сначала добавьте хотя бы одного коллегу');return;}
 if(e?.closed){notify('Сначала возобновите расчёты');return;}
 const participants=e?e.participants.map(p=>({...p})):data.people.filter(p=>p.active).map(p=>({personId:p.id,name:p.name,included:true,expected:data.defaultAmount,reason:''}));
 if(e)data.people.filter(p=>p.active&&!participants.some(x=>x.personId===p.id)).forEach(p=>participants.push({personId:p.id,name:p.name,included:true,expected:data.defaultAmount,reason:''}));
 openForm(e?'Настройки сбора':'Новый сбор',field('Название','title',e?.title||'','text','required maxlength="200"')+`<div class="fields">${field('Дата мероприятия','date',e?.date||`${year}-12-31`,'date','required min="1900-01-01" max="2200-12-31"')}<label class="field">Тип<select name="kind">${[['birthday','День рождения'],['gift','Подарок'],['party','Мероприятие'],['newyear','Новый год'],['other','Другое']].map(([k,n])=>`<option value="${k}" ${k===(e?.kind||'birthday')?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="field">Именинник · для дня рождения<select name="recipient"><option value="">Не выбран</option>${data.people.map(p=>`<option value="${esc(p.id)}" ${p.id===e?.recipientId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="recurring" ${!e||e.recurring?'checked':''}>Повторять на следующий год</label><label class="check"><input type="checkbox" name="monthly" ${e?.monthly?'checked':''}>Собирать по месяцам</label><h3 class="section-title">Участники и план взносов</h3><p class="footnote">Сумма здесь — план, а не полученные деньги. Для ежемесячного сбора укажите сумму за весь период. Именинника исключим автоматически.</p>${participants.map((p,i)=>`<div class="participant-input"><label class="check"><input type="checkbox" name="inc-${i}" ${p.included?'checked':''}><span>${esc(p.name)}</span></label><input type="number" name="sum-${i}" value="${rawRub(p.expected)}" min="0.01" max="1000000000" step="0.01" inputmode="decimal" required aria-label="План взноса ${esc(p.name)}"></div>`).join('')}${e?.collectionClosed?'<p class="footnote">Если план или состав изменятся, сбор будет возобновлён.</p>':''}`,'Сохранить',f=>{
  const title=f.get('title').trim(),date=f.get('date'),recipientId=f.get('kind')==='birthday'?f.get('recipient'):'';
  if(!title||!validDate(date))throw new Error('Проверьте название и дату.');
  const ps=participants.map((p,i)=>({...p,expected:amount(f.get(`sum-${i}`)),included:f.has(`inc-${i}`)&&p.personId!==recipientId,reason:p.personId===recipientId?'Именинник':!f.has(`inc-${i}`)?'Не участвует':''}));
  if(!ps.some(p=>p.included))throw new Error('Выберите хотя бы одного участника.');
  commit(copy=>{const fields={title,date,kind:f.get('kind'),recipientId,recurring:f.has('recurring'),monthly:f.has('monthly'),participants:ps};if(e){const item=copy.events.find(x=>x.id===e.id);if(JSON.stringify(item.participants)!==JSON.stringify(ps))item.collectionClosed=false;Object.assign(item,fields);}else{const item=newEvent(copy,fields);copy.events.push(item);selectedId=item.id;}year=Number(date.slice(0,4));filter='active';mobileDetail=true;},'Сбор сохранён');
 });
}
function paymentForm(personId){const e=activeEvent(),p=e?.participants.find(x=>x.personId===personId);if(!p)return;const t=eventTotals(e),left=Math.max(0,p.expected-t.received(personId));openForm('Получен взнос',`<h3>${esc(p.name)}</h3><p class="footnote">${esc(e.title)} · уже получено ${rub(t.received(personId))}. Сохранение добавит новую оплату.</p><div class="fields">${field('Полученная сумма, ₽','amount',rawRub(left||p.expected),'number','required min="0.01" step="0.01" max="1000000000" inputmode="decimal"')}${field('Дата получения','date',today(),'date','required')}</div>`+noteField(),'Записать взнос',f=>commit(copy=>addPayment(copy.events.find(x=>x.id===e.id),personId,amount(f.get('amount')),f.get('date'),f.get('note').trim()),'Взнос сохранён'));}
function outflowForm(){const e=activeEvent();if(!e)return;const t=eventTotals(e);openForm('Передача денег или расход',`<p class="footnote">${esc(e.title)} · осталось передать ${rub(Math.max(0,t.remaining))}</p><label class="field">Операция<select name="kind"><option value="transfer">Передано имениннику / организатору</option><option value="expense">Оплата подарка или мероприятия</option><option value="return">Возврат участнику</option></select></label><div class="fields">${field('Сумма, ₽','amount',t.remaining>0?rawRub(t.remaining):'','number','required min="0.01" step="0.01" inputmode="decimal"')}${field('Дата','date',today(),'date','required')}</div>`+noteField()+`<p class="footnote">Если передать больше, чем собрано, появится сумма «Передано авансом». Возврат уменьшает остаток у вас, а историю взносов сохраняет.</p>`,'Записать',f=>commit(copy=>addOutflow(copy.events.find(x=>x.id===e.id),amount(f.get('amount')),f.get('date'),f.get('kind'),f.get('note').trim()),'Операция сохранена'));}
function debtForm(id){const d=data.debts.find(x=>x.id===id);openForm(d?'Изменить долг':'Я дал в долг',field('Кому','name',d?.name||'','text','required maxlength="200" list="colleagues"')+`<datalist id="colleagues">${data.people.map(p=>`<option value="${esc(p.name)}"></option>`).join('')}</datalist>`+field('Выдано, ₽','amount',d?rawRub(d.amount):'','number','required min="0.01" step="0.01" inputmode="decimal"')+`<div class="fields">${field('Дата выдачи','date',d?.date||today(),'date','required')}${field('Срок возврата · необязательно','due',d?.due||'','date')}</div>`+noteField(d?.note),'Сохранить',f=>{
 const date=f.get('date'),due=f.get('due'),sum=amount(f.get('amount')),name=f.get('name').trim();if(!name||!validDate(date)||due&&(!validDate(due)||due<date))throw new Error('Проверьте имя и даты.');if(d&&(sum<d.amount-debtRemaining(d)||d.repayments.some(p=>p.date<date)))throw new Error('Сумма или дата противоречат уже записанным возвратам.');
 commit(copy=>{const fields={name,date,due,amount:sum,note:f.get('note').trim()};if(d)Object.assign(copy.debts.find(x=>x.id===d.id),fields);else copy.debts.push({id:uid(),...fields,repayments:[]});},'Долг сохранён');
});}
function repaymentForm(id){const d=data.debts.find(x=>x.id===id);if(!d)return;openForm('Получен возврат',`<h3>${esc(d.name)}</h3><div class="amount-big">Осталось ${rub(debtRemaining(d))}</div><div class="fields">${field('Вернули, ₽','amount',rawRub(debtRemaining(d)),'number',`required min="0.01" step="0.01" max="${rawRub(debtRemaining(d))}" inputmode="decimal"`)}${field('Дата возврата','date',today(),'date',`required min="${d.date}"`)}</div>`+noteField(),'Записать возврат',f=>commit(copy=>addRepayment(copy.debts.find(x=>x.id===d.id),amount(f.get('amount')),f.get('date'),f.get('note').trim()),'Возврат сохранён'));}
function planningForm(mode){
 const isCopy=mode==='copy';
 openForm(isCopy?'Сборы на следующий год':'Дни рождения на год',`${isCopy?field('Из года','source',year,'number','required min="1900" max="2199"'):''}${field('Создать на год','target',isCopy?year+1:year,'number','required min="1900" max="2200"')}<div id="plan-list"></div>`,'Создать выбранные',(f,form)=>{
  const target=Number(f.get('target')),source=Number(f.get('source')),candidates=isCopy?annualCandidates(data,source,target):birthdayCandidates(data,target);const selected=new Set(f.getAll('candidate'));const chosen=candidates.filter(e=>selected.has(isCopy?e.seriesId:e.recipientId));if(!chosen.length)throw new Error('Выберите хотя бы одно мероприятие.');
  commit(copy=>{copy.events.push(...chosen);year=target;filter='active';selectedId=chosen[0].id;mobileDetail=false;},`Создано сборов: ${chosen.length}`);
 });
 const update=()=>{const form=modal.querySelector('form'),f=new FormData(form),target=Number(f.get('target')),source=Number(f.get('source'));try{const candidates=isCopy?annualCandidates(data,source,target):birthdayCandidates(data,target);modal.querySelector('#plan-list').innerHTML=`<p class="footnote">${isCopy?'Копируются выбранные регулярные мероприятия. Ушедших коллег исключим, новых добавим. Суммы оплат и расчёты обнуляются.':'Именинники автоматически исключаются из своего сбора.'} Уже созданные мероприятия не дублируются.</p>${candidates.map(e=>`<label class="candidate"><input type="checkbox" name="candidate" value="${esc(isCopy?e.seriesId:e.recipientId)}" checked><span class="grow">${esc(e.title)}<span class="muted" style="display:block">${dateText(e.date)} · участников ${e.participants.filter(p=>p.included).length}</span></span></label>`).join('')||'<p class="footnote">Нет мероприятий для создания. Добавьте дни рождения коллег или отметьте существующие сборы как повторяющиеся.</p>'}`;}catch(e){modal.querySelector('#plan-list').innerHTML=`<p class="error">${esc(e.message)}</p>`;}};
 modal.querySelectorAll('input[type=number]').forEach(x=>x.addEventListener('input',update));update();
}
function downloadBackup(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`svoi-dengi-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Резервная копия скачана');}
function importForm(){openForm('Восстановить данные','<p class="footnote">Выберите JSON-копию, скачанную из этого приложения. После проверки покажем, что будет восстановлено.</p><label class="field">Резервная копия<input name="file" type="file" accept=".json,application/json" required></label>','Проверить файл',async f=>{const file=f.get('file');if(file.size>10000000)throw new Error('Файл слишком большой: максимум 10 МБ.');let imported;try{imported=validateData(JSON.parse(await file.text()));}catch{throw new Error('Файл повреждён или имеет неподдерживаемый формат.');}setTimeout(()=>confirmAction('Заменить данные?',`В копии: коллег ${imported.people.length}, мероприятий ${imported.events.length}, долгов ${imported.debts.length}. Текущие записи будут заменены. Перед заменой будет скачана копия текущих данных.`,()=>{if(!loadError)downloadBackup();commit(copy=>Object.assign(copy,imported),'Данные восстановлены',true);year=currentYear();selectedId='';mobileDetail=false;render();},'Восстановить'),0);});}
app.addEventListener('change',ev=>{if(ev.target.id==='year'){year=Number(ev.target.value);selectedId='';mobileDetail=false;render();}});
async function dispatch(button){
 const action=button.dataset.action,id=button.dataset.id,e=activeEvent();
 switch(action){
 case 'nav':section=id;mobileDetail=false;render();window.scrollTo({top:0});break;
 case 'back':mobileDetail=false;render();break;
 case 'select-event':selectedId=id;mobileDetail=true;render();break;
 case 'filter':filter=id;mobileDetail=false;render();break;
 case 'debt-filter':debtFilter=id;render();break;
 case 'new-person':personForm();break;
 case 'edit-person':personForm(id);break;
 case 'new-event':eventForm();break;
 case 'edit-event':eventForm(true);break;
 case 'payment':paymentForm(id);break;
 case 'outflow':outflowForm();break;
 case 'new-debt':debtForm();break;
 case 'edit-debt':debtForm(id);break;
 case 'repayment':repaymentForm(id);break;
 case 'finish-collection':confirmAction('Завершить сбор?', 'Все необходимые взносы получены. После завершения можно продолжать передачи и расходы.',()=>commit(copy=>closeCollection(copy.events.find(x=>x.id===e.id)),'Сбор завершён'));break;
 case 'finish-event':confirmAction('Завершить расчёты?', 'Остаток равен нулю. Мероприятие будет перемещено в архив.',()=>commit(copy=>closeEvent(copy.events.find(x=>x.id===e.id)),'Расчёты завершены'));break;
 case 'reopen-collection':commit(copy=>{const event=copy.events.find(x=>x.id===e.id);event.collectionClosed=false;event.closed=false;},'Сбор возобновлён');break;
 case 'reopen-event':commit(copy=>{copy.events.find(x=>x.id===e.id).closed=false;filter='active';},'Расчёты возобновлены');break;
 case 'delete-operation':confirmAction('Удалить операцию?', 'Будет удалена только выбранная операция. Остаток пересчитается.',()=>commit(copy=>{const event=copy.events.find(x=>x.id===e.id);if(event.closed||button.dataset.kind==='payment'&&event.collectionClosed)throw new Error('Сначала возобновите сбор или расчёты.');const key=button.dataset.kind==='payment'?'payments':'outflows';event[key]=event[key].filter(x=>x.id!==id);},'Операция удалена'),'Удалить');break;
 case 'delete-repayment':confirmAction('Удалить возврат?', 'Остаток долга увеличится на сумму удалённого возврата.',()=>commit(copy=>{const d=copy.debts.find(x=>x.id===button.dataset.debt);d.repayments=d.repayments.filter(p=>p.id!==id);},'Возврат удалён'),'Удалить');break;
 case 'birthdays':planningForm('birthday');break;
 case 'next-year':planningForm('copy');break;
 case 'backup':downloadBackup();break;
 case 'import':importForm();break;
 case 'demo':if(data.events.length||data.people.length||data.debts.length)throw new Error('Пример доступен только в пустом приложении.');commit(copy=>Object.assign(copy,demoData()),'Демонстрационные данные загружены');break;
 case 'default-amount':openForm('Взнос по умолчанию',field('Сумма, ₽','amount',rawRub(data.defaultAmount),'number','required min="0.01" step="0.01" inputmode="decimal"'),'Сохранить',f=>commit(copy=>{copy.defaultAmount=amount(f.get('amount'));},'Сумма сохранена'));break;
 case 'reset':openForm('Очистить все данные','<p class="footnote">Все записи этого устройства будут удалены. Перед очисткой скачайте резервную копию.</p>'+field('Для подтверждения напишите УДАЛИТЬ','confirmation','','text','required'),'Удалить всё',f=>{if(f.get('confirmation')!=='УДАЛИТЬ')throw new Error('Введите УДАЛИТЬ.');if(!loadError)downloadBackup();commit(copy=>Object.assign(copy,emptyData()),'Все данные удалены',true);selectedId='';year=currentYear();render();});break;
 case 'install':if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;render();}break;
 case 'close-modal':modal.close();break;
 }
}
document.addEventListener('click',ev=>{const button=ev.target.closest('button[data-action]');if(button&&!button.disabled)dispatch(button).catch(error=>notify(error.message));});
window.addEventListener('storage',ev=>{if(ev.key!==KEY)return;try{const incoming=ev.newValue?validateData(JSON.parse(ev.newValue)):emptyData();data=incoming;lastRaw=ev.newValue;loadError='';if(modal.open){modal.close();notify('Данные изменились в другой вкладке. Форма закрыта, повторите действие.');}render();}catch{loadError='В другой вкладке появились некорректные данные. Восстановите резервную копию.';render();}});
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev;if(section==='settings')render();});
window.addEventListener('online',render);window.addEventListener('offline',render);
render();
if('serviceWorker' in navigator && window.isSecureContext){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;render();}).catch(()=>{offlineReady=false;});}
